// FUNCTION: BFME2 0x00237E63 size=94 name=?rva00237E63@Version@@QAEHPBX_N@Z evidence=?:placeholder tier=B hypothesis:name:Z
Int Version::getVersionColor(const Version *other, Bool ignoreSame)
{
	Bool same = !ignoreSame && m_major == other->m_major && m_minor == other->m_minor
            && m_buildNum == other->m_buildNum && m_localBuildNum == other->m_localBuildNum;

	switch (other->m_major)
	{
	case 1:
		return same ? (Int)0xFF7AAB44 : (Int)0xFF3D5522;
	case 2:
		return same ? (Int)0xFF747BCE : (Int)0xFF3A3D67;
	}
	return (Int)0xFF646464;
}

